 private EditText input(String hint,String value,boolean password){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setSingleLine(true);e.setTextSize(16);e.setSaveEnabled(false);e.setPadding(dp(14),0,dp(14),0);e.setBackground(panel(Color.WHITE,12));e.setInputType(password?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD:InputType.TYPE_CLASS_TEXT);LinearLayout.LayoutParams field=new LinearLayout.LayoutParams(-1,dp(54));field.setMargins(0,dp(6),0,dp(6));content.addView(e,field);return e;}
