 private void message(String msg){if(notice!=null){notice.setText(msg);notice.setVisibility(msg==null||msg.isEmpty()?View.GONE:View.VISIBLE);}}
 private void failure(String msg){message(msg);Toast.makeText(this,L10n.t(msg==null?"Գործողությունը չի կատարվել":msg),Toast.LENGTH_LONG).show();}
 private interface Work {Object run()throws Exception;}private interface Done{void accept(Object value)throws Exception;}
 private void task(Work work,Done done){if(busy)return;busy=true;if(loading!=null)loading.setVisibility(View.VISIBLE);message("Բեռնվում է…");executor.submit(()->{try{Object result=work.run();runOnUiThread(()->{if(destroyed)return;busy=false;if(loading!=null)loading.setVisibility(View.GONE);try{done.accept(result);}catch(Exception e){failure(e.getMessage());}});}catch(Exception e){runOnUiThread(()->{if(destroyed)return;busy=false;if(loading!=null)loading.setVisibility(View.GONE);if(e instanceof ApiClient.ApiError&&((ApiClient.ApiError)e).status==401){clear();login();}failure(e.getMessage()==null?"Գործողությունը չի կատարվել":e.getMessage());});}});}
