 private void login(){if(AppSession.user!=null){AppSession.clear();finish();return;}clear();currentScreen="login";screen("ZZWS — կառավարում");message("Տարբերակ "+EndpointConfiguration.VERSION+(EndpointConfiguration.RELEASE?" • աշխատանքային տարբերակ":" • անցանց ստուգում։ Աշխատանքային Supabase-ն արգելափակված է։"));root.setBackgroundColor(NAVY);notice.setTextColor(Color.rgb(205,220,235));content.setPadding(dp(16),dp(18),dp(16),dp(18));content.setBackground(panel(Color.rgb(245,248,252),20));
  try{ImageView logo=new ImageView(this);try(java.io.InputStream image=getAssets().open("logo.png")){logo.setImageBitmap(android.graphics.BitmapFactory.decodeStream(image));}logo.setAdjustViewBounds(true);logo.setContentDescription("ZZWS տարբերանշան");content.addView(logo,new LinearLayout.LayoutParams(-1,dp(58)));}catch(java.io.IOException ignored){}
  if(!EndpointConfiguration.RELEASE){content.addView(text("Ցուցադրում առանց համացանցի",19));content.addView(text("Միայն փորձնական պատվերներ։ Փոփոխությունները պահվում են հիշողության մեջ և հեռացվում են դուրս գալուց հետո։",14));
  Spinner demoRole=new Spinner(this);demoRole.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Ցուցադրում՝ կառավարիչ","Ցուցադրում՝ միայն դիտում"}));content.addView(demoRole);
  button("Բացել անցանց ցուցադրումը",()->{demoMode=true;demo=new DemoStore();logged=true;write=demoRole.getSelectedItemPosition()==0;list();});
  }
  content.addView(text(EndpointConfiguration.RELEASE?"Մուտք ZZWS":"Մուտք միասնական փորձնական API-ով",19));
  EditText server=input("Միասնական API-ի հասցե",EndpointConfiguration.RELEASE?EndpointConfiguration.API:"http://10.0.2.2:8080/functions/v1/zzws-api/",false),key=input("Միայն հրապարակային բանալի",EndpointConfiguration.RELEASE?EndpointConfiguration.PUBLIC_KEY:"offline-public",false),name=input("Ադմինիստրատորի մուտքանուն","",false),password=input("Գաղտնաբառ՝ միայն թվանշաններ","",true);
  if(EndpointConfiguration.RELEASE){server.setVisibility(View.GONE);key.setVisibility(View.GONE);}
  button(EndpointConfiguration.RELEASE?"Մուտք գործել":"Մուտք գործել փորձնական սերվեր",()->{String pass=password.getText().toString(),url=server.getText().toString().trim(),publicKey=key.getText().toString().trim(),login=name.getText().toString().trim();password.setText("");task(()->{api.configure(url,publicKey);return api.call("POST","login",new JSONObject().put("login",login).put("password",pass));},value->{JSONObject result=(JSONObject)value;if(result.optBoolean("mfaRequired")){mfa(result.optString("challengeToken"));return;}verify();});});
  content.addView(text(EndpointConfiguration.RELEASE?"Աշխատաշրջանը պահվում է միայն հիշողության մեջ։ Հասանելիությունը և իրավունքները ստուգվում են ZZWS սերվերում։":"Աշխատաշրջանը պահվում է միայն հիշողության մեջ։ Հեռախոսի համար նշեք փորձնական միջավայրի HTTPS հասցեն, նմանակիչի համար՝ 10.0.2.2։ Մի մուտքագրեք ծառայողական կամ գաղտնի բանալի։",13));
 }
 private void mfa(String token){screen("Մուտքի հաստատում");EditText code=input("Հավելվածի վեցանիշ կոդ","",true);button("Հաստատել",()->{String value=code.getText().toString();code.setText("");task(()->api.call("POST","login/mfa",new JSONObject().put("challengeToken",token).put("code",value)),r->verify());});button("Հետ",this::login);}
 private void verify(){task(()->api.call("GET","me",null),value->{JSONObject user=(JSONObject)value;JSONArray permissions=user.optJSONArray("permissions");boolean access=user.optJSONObject("capabilities")!=null&&user.getJSONObject("capabilities").optBoolean("mobileAdmin");access=access||user.optBoolean("mobileAdminEnabled");if(!"admin".equals(user.optString("role"))||!access||!contains(permissions,"orders:read")||user.optBoolean("needsPasswordSetup")){clear();login();message("Ադմինիստրատորի քարտում հավելվածի հասանելիությունը միացված չէ, կամ նախ պետք է կայքում սահմանել գաղտնաբառը։");return;}write=contains(permissions,"orders:write");demoMode=false;logged=true;list();schedulePoll();});}
 private boolean contains(JSONArray a,String s){if(a==null)return false;for(int i=0;i<a.length();i++)if(s.equals(a.optString(i)))return true;return false;}
 private String status(String key){for(int i=0;i<KEYS.length;i++)if(KEYS[i].equals(key))return LABELS[i];return key;}
 private String amount(double n){return String.format(new java.util.Locale("hy","AM"),"%,.2f ֏",n);}
 private String time(String value){try{return DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm:ss").withZone(ZoneId.of("Asia/Yerevan")).format(Instant.parse(value))+" (Երևան)";}catch(Exception e){return value;}}
 private void navigation(String active){LinearLayout bar=new LinearLayout(this);bar.setPadding(0,dp(8),0,dp(2));bar.setBackground(panel(Color.WHITE,14));String[] titles={"Կառավարում","Պատվերներ","Վիճակագրություն","Կարգավորումներ"};Runnable[] actions={this::finish,this::list,this::statistics,this::settings};for(int i=0;i<titles.length;i++){final Runnable action=actions[i];TextView item=text(titles[i],11);item.setGravity(Gravity.CENTER);item.setSingleLine(true);item.setAutoSizeTextTypeUniformWithConfiguration(8,12,1,android.util.TypedValue.COMPLEX_UNIT_SP);item.setTextColor(active.equals(titles[i])?BLUE:MUTED);item.setMinHeight(dp(48));item.setOnClickListener(v->{if(!busy)action.run();});bar.addView(item,new LinearLayout.LayoutParams(0,-2,1));}root.addView(bar);}
 private LinearLayout card(LinearLayout parent){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(14),dp(12),dp(14),dp(12));box.setBackground(panel(Color.WHITE,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(6));parent.addView(box,lp);return box;}
 private void label(LinearLayout parent,String value,int size,boolean bold){TextView t=text(value,size);if(bold)t.setTypeface(null,1);parent.addView(t);}
 private int statusColor(String value){switch(value){case "new":return Color.rgb(231,73,73);case "confirmed":return BLUE;case "in_progress":return Color.rgb(191,126,0);case "completed":case "received":return Color.rgb(0,153,87);default:return MUTED;}}
 private void badge(LinearLayout parent,String value){TextView tag=text(status(value),13);tag.setTypeface(null,1);tag.setTextColor(statusColor(value));tag.setPadding(dp(10),dp(6),dp(10),dp(6));tag.setBackground(panel(Color.rgb(238,243,250),8));parent.addView(tag,new LinearLayout.LayoutParams(-2,-2));}
 private String listPath(){return "admin/orders?search="+encode(search)+"&status="+encode(statusFilter)+"&from="+encode(fromDate)+"&to="+encode(toDate);}
 private String encode(String value){try{return URLEncoder.encode(value,"UTF-8");}catch(Exception e){return "";}}
 private void list(){
  currentScreen="orders";selectedId="";selected=null;screen("ZZWS — պատվերներ");
  message((demoMode?"Անցանց ցուցադրում • ":(EndpointConfiguration.RELEASE?"Աշխատանքային միջավայր • ":"Փորձնական միջավայր • "))+(write?"Կառավարիչ":"Միայն դիտում"));
  EditText query=input("Որոնել պատվիրատուին կամ պատվերի համարը",search,false);
  query.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);
  query.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH&&!busy){search=query.getText().toString().trim();list();return true;}return false;});
  button("Որոնել",()->{search=query.getText().toString().trim();list();});button("Զտիչներ",this::filters);
  HorizontalScrollView chips=new HorizontalScrollView(this);LinearLayout strip=new LinearLayout(this);chips.setHorizontalScrollBarEnabled(false);chips.addView(strip);
  String[] keys={"","new","in_progress","completed"};String[] labels={"Բոլորը","Նոր","Ընթացքում","Առաքված"};
  for(int i=0;i<keys.length;i++){final String key=keys[i];TextView chip=text(labels[i],13);chip.setPadding(dp(12),dp(10),dp(12),dp(10));chip.setBackground(panel(key.equals(statusFilter)?BLUE:Color.WHITE,10));chip.setTextColor(key.equals(statusFilter)?Color.WHITE:NAVY);chip.setOnClickListener(v->{if(!busy){statusFilter=key;list();}});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.setMargins(0,0,dp(6),0);strip.addView(chip,lp);}
  content.addView(chips);orderRows=new LinearLayout(this);orderRows.setOrientation(LinearLayout.VERTICAL);content.addView(orderRows);navigation("Պատվերներ");
  task(()->demoMode?filteredDemo():api.call("GET",listPath(),null).getJSONArray("orders"),value->renderOrderRows((JSONArray)value));
 }
 private void renderOrderRows(JSONArray orders)throws Exception{
  if(orderRows==null||!"orders".equals(currentScreen))return;
  LinearLayout rows=orderRows;rows.removeAllViews();orderListFingerprint=orders.toString();
  message((demoMode?"Անցանց ցուցադրում • ":(EndpointConfiguration.RELEASE?"Աշխատանքային միջավայր • ":"Փորձնական միջավայր • "))+"Պատվերներ՝ "+orders.length()+(orders.length()==100?" • վերջին 100 արդյունքը":""));
  if(orders.length()==0)label(rows,"Համապատասխան պատվերներ չկան",16,false);
  for(int i=0;i<orders.length();i++){
   JSONObject o=orders.getJSONObject(i);LinearLayout box=card(rows);label(box,"№"+o.optLong("number"),18,true);badge(box,o.optString("status"));
   JSONObject customer=o.optJSONObject("customer");label(box,customer==null?"—":customer.optString("client","—"),16,false);
   JSONObject author=o.optJSONObject("created_by");if(author!=null)label(box,"Լրացրել է՝ "+author.optString("name")+" ("+author.optString("login")+")",13,false);
   label(box,time(o.optString("created")),12,false);label(box,amount(o.optDouble("total")),18,true);String id=o.getString("id");box.setContentDescription("Բացել պատվեր №"+o.optLong("number"));box.setFocusable(true);box.setOnClickListener(v->{if(!busy)open(id);});
  }
  if(orders.length()==100)label(rows,"Որոնումը սահմանափակեք ամսաթվով կամ պատվիրատուով՝ ավելի հին պատվերները գտնելու համար։",14,false);
 }
 private JSONArray filteredDemo()throws Exception{JSONArray source=demo.list(search,statusFilter),out=new JSONArray();for(int i=0;i<source.length();i++){JSONObject o=source.getJSONObject(i);String day=Instant.parse(o.getString("created")).atZone(ZoneId.of("Asia/Yerevan")).toLocalDate().toString();if((fromDate.isEmpty()||day.compareTo(fromDate)>=0)&&(toDate.isEmpty()||day.compareTo(toDate)<=0))out.put(o);}return out;}
 private void chooseDate(EditText field){java.time.LocalDate now=java.time.LocalDate.now(ZoneId.of("Asia/Yerevan"));try{now=java.time.LocalDate.parse(field.getText());}catch(Exception ignored){}new DatePickerDialog(this,(v,y,m,d)->field.setText(String.format(java.util.Locale.ROOT,"%04d-%02d-%02d",y,m+1,d)),now.getYear(),now.getMonthValue()-1,now.getDayOfMonth()).show();}
 private void filters(){currentScreen="filters";screen("Պատվերների զտիչներ");label(content,"Կարգավիճակ",18,true);Spinner filter=new Spinner(this);String[] names=new String[LABELS.length+1];names[0]="Բոլոր կարգավիճակները";System.arraycopy(LABELS,0,names,1,LABELS.length);filter.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));for(int i=0;i<KEYS.length;i++)if(KEYS[i].equals(statusFilter))filter.setSelection(i+1);content.addView(filter);label(content,"Ժամանակահատված՝ Երևանի ժամանակով",18,true);EditText from=input("Սկսած ամսաթվից",fromDate,false),to=input("Մինչև ամսաթիվը ներառյալ",toDate,false);for(EditText field:new EditText[]{from,to}){field.setFocusable(false);field.setOnClickListener(v->chooseDate(field));}button("Կիրառել",()->{String start=from.getText().toString(),end=to.getText().toString();if(!start.isEmpty()&&!end.isEmpty()&&start.compareTo(end)>0){message("Սկզբի ամսաթիվը պետք է լինի ավարտից առաջ։");return;}fromDate=start;toDate=end;statusFilter=filter.getSelectedItemPosition()==0?"":KEYS[filter.getSelectedItemPosition()-1];list();});button("Մաքրել զտիչները",()->{fromDate=toDate=statusFilter=search="";list();});button("Վերադառնալ",this::list);}
