 private boolean editableStatus(JSONObject o){return o.optString("received_at").isEmpty()&&!java.util.Arrays.asList("received","completed","rejected").contains(o.optString("status"));}
 private void renderOrderLines(JSONObject o)throws Exception{
  JSONArray lines=o.optJSONArray("lines"),original=o.optJSONArray("original_lines");java.util.LinkedHashMap<String,JSONObject> before=new java.util.LinkedHashMap<>(),now=new java.util.LinkedHashMap<>();
  if(original!=null)for(int i=0;i<original.length();i++){JSONObject l=original.getJSONObject(i);before.put(l.optString("articul"),l);}if(lines!=null)for(int i=0;i<lines.length();i++){JSONObject l=lines.getJSONObject(i);now.put(l.optString("articul"),l);}
  java.util.LinkedHashSet<String> codes=new java.util.LinkedHashSet<>(before.keySet());codes.addAll(now.keySet());label(content,"Ապրանքներ ("+codes.size()+")",20,true);
  for(String code:codes){JSONObject old=before.get(code),line=now.get(code),shown=line!=null?line:old;LinearLayout box=card(content);TextView title=text(shown.optString("name"),17);if(line==null)title.setPaintFlags(title.getPaintFlags()|android.graphics.Paint.STRIKE_THRU_TEXT_FLAG);box.addView(title);label(box,code,12,false);int qty=line==null?0:line.optInt("qty");if(old!=null&&old.optInt("qty")!=qty){TextView initial=text(""+old.optInt("qty"),15);initial.setPaintFlags(initial.getPaintFlags()|android.graphics.Paint.STRIKE_THRU_TEXT_FLAG);box.addView(initial);}if(old!=null&&line!=null&&old.optDouble("unitPrice")!=line.optDouble("unitPrice")){TextView initial=text(amount(old.optDouble("unitPrice")),15);initial.setPaintFlags(initial.getPaintFlags()|android.graphics.Paint.STRIKE_THRU_TEXT_FLAG);box.addView(initial);}label(box,line==null?"Հեռացված է":qty+" × "+amount(line.optDouble("unitPrice")),15,false);}
 }
 private void statusEditor(){if(!write||selected==null||!editableStatus(selected))return;currentScreen="status";JSONObject o=selected;screen("Փոխել կարգավիճակը");label(content,"Պատվեր №"+o.optLong("number")+" • "+amount(o.optDouble("total")),19,true);RadioGroup options=new RadioGroup(this);for(int i=0;i<5;i++){RadioButton option=new RadioButton(this);option.setId(100+i);option.setText(LABELS[i]);option.setTextSize(17);option.setPadding(dp(8),dp(12),dp(8),dp(12));options.addView(option);if(KEYS[i].equals(o.optString("status")))options.check(100+i);}content.addView(options);EditText comment=input("Մեկնաբանություն",o.optString("comment"),false);comment.setSingleLine(false);comment.setMinLines(2);button("Պահպանել",()->{int position=options.getCheckedRadioButtonId()-100;if(position<0||position>=5){message("Ընտրեք կարգավիճակը։");return;}String next=KEYS[position],note=comment.getText().toString();new AlertDialog.Builder(this).setTitle(L10n.t("Հաստատել փոփոխությունը")).setMessage(L10n.t("Պատվեր №"+o.optLong("number")+" → "+status(next))).setNegativeButton(L10n.t("Չեղարկել"),null).setPositiveButton(L10n.t("Պահպանել"),(d,w)->saveStatus(o,next,note)).show();});button("Չեղարկել",()->{try{detail();}catch(Exception e){failure(e.getMessage());}});}
 private void saveStatus(JSONObject old,String status,String comment){String id=old.optString("id");int revision=old.optInt("revision");task(()->demoMode?demo.status(id,revision,status,comment):api.call("POST","admin/orders/status",new JSONObject().put("id",id).put("revision",revision).put("status",status).put("comment",comment)),value->{if(demoMode)NotificationBridge.show(this,"ZZWS փորձարկում — պատվերը փոփոխվել է","№"+old.optLong("number")+" · "+status(status),old.optInt("number"));open(id);});}
 private void history(String id){currentScreen="history";screen("Պատվերի պատմություն");task(()->demoMode?demo.history(id):api.call("GET","admin/orders/events?orderId="+URLEncoder.encode(id,"UTF-8"),null).getJSONArray("events"),value->{JSONArray events=(JSONArray)value;message("Իրադարձություններ՝ "+events.length()+" • Երևանի ժամանակով");for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);String type=eventLabel(e.optString("event_type"));content.addView(text("Տարբերակ "+e.optInt("revision")+" · "+type+"\n"+time(e.optString("occurred_at",e.optString("created"))),16));JSONObject changes=e.optJSONObject("changes");if(changes!=null){java.util.Iterator<String> keys=changes.keys();StringBuilder fields=new StringBuilder();while(keys.hasNext()){if(fields.length()>0)fields.append(", ");fields.append(fieldLabel(keys.next()));}content.addView(text("Փոփոխված դաշտեր՝ "+fields,14));}}if(events.length()==0)content.addView(text("Հին պատվերների նոր մատյանը կարող է դատարկ լինել։ Չգրանցված պատմություն չի ստեղծվում։",16));button("Վերադառնալ պատվերին",()->open(id));});}
 private void schedulePoll(){timer.removeCallbacksAndMessages(null);if(!logged||demoMode)return;timer.postDelayed(()->{if(logged&&!demoMode&&!busy)poll();else schedulePoll();},pollDelayMs);}
 private void poll(){executor.submit(()->{try{JSONObject me=api.call("GET","me",null);if(!"admin".equals(me.optString("role"))||!me.optBoolean("mobileAdminEnabled")||!contains(me.optJSONArray("permissions"),"orders:read")){runOnUiThread(()->{if(!destroyed)login();});return;}int seconds=me.optInt("ordersRefreshSeconds",5);pollDelayMs=(seconds>=5&&seconds<=300?seconds:5)*1000L;if("orders".equals(currentScreen)&&!busy){JSONArray latest=api.call("GET",listPath(),null).getJSONArray("orders");runOnUiThread(()->{if(!destroyed&&!busy&&"orders".equals(currentScreen)&&!latest.toString().equals(orderListFingerprint)){try{renderOrderRows(latest);}catch(Exception ignored){message("Չհաջողվեց թարմացնել պատվերները։ Կրկին բացեք ցանկը։");}}});}}catch(Exception e){if(e instanceof ApiClient.ApiError&&(((ApiClient.ApiError)e).status==401||((ApiClient.ApiError)e).status==403)){runOnUiThread(()->{if(!destroyed)login();});return;}}runOnUiThread(()->{if(!destroyed)schedulePoll();});});}
 @Override protected void onStop(){super.onStop();timer.removeCallbacksAndMessages(null);}
 @Override protected void onStart(){super.onStart();if(logged&&!demoMode){schedulePoll();}}
 @Override protected void onDestroy(){destroyed=true;timer.removeCallbacksAndMessages(null);executor.shutdownNow();super.onDestroy();}
 private void navigateBack(){if(destroyed||isFinishing())return;if(busy){message("Սպասեք հարցման ավարտին։ Փոփոխությունն ինքնաշխատ չի կրկնվում։");return;}if(!logged){finish();return;}switch(ManagementNavigationKt.managerBackDestination(currentScreen)){case "detail":try{detail();}catch(Exception e){failure(e.getMessage());}break;case "orders":list();break;default:finish();}}
 private static String eventLabel(String value){switch(value){case "order.created":return "Պատվերը ստեղծվել է";case "order.updated":return "Պատվերը փոփոխվել է";case "order.status_changed":return "Կարգավիճակը փոփոխվել է";case "order.received":return "Ստացումը հաստատվել է";case "order.cancelled":return "Պատվերը չեղարկվել է";default:return "Պատվերի իրադարձություն";}}
 private static String fieldLabel(String value){switch(value){case "lines":return "Ապրանքներ";case "total":return "Ընդհանուր գումար";case "status":return "Կարգավիճակ";case "delivery":return "Առաքում";case "comment":return "Մեկնաբանություն";default:return "Լրացուցիչ տվյալներ";}}
